// 数组去重函数，但有 bug

// bug：用了 indexOf 但比较方式有问题，NaN 和对象去重不对
export function dedupe<T>(arr: T[]): T[] {
  const result: T[] = []
  for (const item of arr) {
    // bug: 这里用 == 而不是正确的比较
    if (result.indexOf(item) === -1) {
      result.push(item)
    }
  }
  return result
}

