import { test, expect } from 'bun:test'
import { dedupe } from './dedupe'

test('数字去重', () => {
  expect(dedupe([1, 2, 2, 3, 3, 3])).toEqual([1, 2, 3])
})

test('空数组', () => {
  expect(dedupe([])).toEqual([])
})

test('字符串去重', () => {
  expect(dedupe(['a', 'b', 'a', 'c'])).toEqual(['a', 'b', 'c'])
})

test('保持顺序', () => {
  expect(dedupe([3, 1, 2, 1, 3])).toEqual([3, 1, 2])
})
